import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Bat：一种具有语法高亮和 Git 集成的 Cat 类命令 | LCTT x X-CMD","titleTemplate":false,"description":"Bat：一种具有语法高亮和 Git 集成的 Cat 类命令 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bat：一种具有语法高亮和 Git 集成的 Cat 类命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bat：一种具有语法高亮和 Git 集成的 Cat 类命令 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration","title":"Bat：一种具有语法高亮和 Git 集成的 Cat 类命令","tag":"201809","desc":""},"relativePath":"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration.md","filePath":"[post].md"}'),h={name:"201809/20180828 A Cat Clone With Syntax Highlighting And Git Integration.md"};function g(c,t,b,u,k,m){const a=o("Link");return d(),r("div",null,[t[23]||(t[23]=p('<h1 id="bat-一种具有语法高亮和-git-集成的-cat-类命令" tabindex="-1">Bat：一种具有语法高亮和 Git 集成的 Cat 类命令 <a class="header-anchor" href="#bat-一种具有语法高亮和-git-集成的-cat-类命令" aria-label="Permalink to “Bat：一种具有语法高亮和 Git 集成的 Cat 类命令”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/Bat-command-720x340.png" alt=""></p><p>在类 UNIX 系统中，我们使用 <code>cat</code> 命令去打印和连接文件。使用 <code>cat</code> 命令，我们能将文件目录打印到到标准输出，合成几个文件为一个目标文件，还有追加几个文件到目标文件中。今天，我偶然发现一个具有相似作用的命令叫做 “Bat” ，它是 <code>cat</code> 命令的一个克隆版，具有一些例如语法高亮、 Git 集成和自动分页等非常酷的特性。在这个简略指南中，我们将讲述如何在 Linux 中安装和使用 <code>bat</code> 命令。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>Bat 可以在 Arch Linux 的默认软件源中获取。 所以你可以使用 <code>pacman</code> 命令在任何基于 arch 的系统上来安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S bat</span></span></code></pre></div>',6)),n("p",null,[t[1]||(t[1]=s("在 Debian、Ubuntu、Linux Mint 等系统中，从其",-1)),i(a,{href:"https://github.com/sharkdp/bat/releases"},{default:e(()=>[...t[0]||(t[0]=[s("发布页面",-1)])]),_:1}),t[2]||(t[2]=s("下载 ",-1)),t[3]||(t[3]=n("strong",null,".deb",-1)),t[4]||(t[4]=s(" 文件，然后用下面的命令来安装。",-1))]),t[24]||(t[24]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gdebi</span></span>
<span class="line"><span>$ sudo gdebi bat_0.5.0_amd64.deb</span></span></code></pre></div><p>对于其他系统，你也许需要从软件源编译并安装。确保你已经安装了 Rust 1.26 或者更高版本。</p><p>然后运行以下命令来安装 Bat：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cargo install bat</span></span></code></pre></div>`,4)),n("p",null,[t[6]||(t[6]=s("或者，你可以从 ",-1)),i(a,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:e(()=>[...t[5]||(t[5]=[s("Linuxbrew",-1)])]),_:1}),t[7]||(t[7]=s(" 软件包管理中来安装它。",-1))]),t[25]||(t[25]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install bat</span></span></code></pre></div><h3 id="bat-命令的使用" tabindex="-1">bat 命令的使用 <a class="header-anchor" href="#bat-命令的使用" aria-label="Permalink to “bat 命令的使用”">​</a></h3><p><code>bat</code> 命令的使用与 <code>cat</code> 命令的使用非常相似。</p><p>使用 <code>bat</code> 命令创建一个新的文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat &gt; file.txt</span></span></code></pre></div><p>使用 <code>bat</code> 命令来查看文件内容，只需要:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file.txt</span></span></code></pre></div><p>你能同时查看多个文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file1.txt file2.txt</span></span></code></pre></div><p>将多个文件的内容合并至一个单独文件中:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat file1.txt file2.txt file3.txt &gt; document.txt</span></span></code></pre></div><p>就像我之前提到的那样，除了浏览和编辑文件以外，<code>bat</code> 命令有一些非常酷的特性。</p><p><code>bat</code> 命令支持大多数编程和标记语言的<ruby>语法高亮<rt>syntax highlighting</rt></ruby>。比如，下面这个例子。我将使用 <code>cat</code> 和 <code>bat</code> 命令来展示 <code>reverse.py</code> 的内容。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-and-cat-command-output-comparison.png" alt=""></p><p>你注意到区别了吗？ <code>cat</code> 命令以纯文本格式显示文件的内容，而 <code>bat</code> 命令显示了语法高亮和整齐的文本对齐格式。更好了不是吗？</p><p>如果你只想显示行号（而没有表格）使用 <code>-n</code> 标记。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat -n reverse.py</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-3.png" alt=""></p><p>另一个 <code>bat</code> 命令中值得注意的特性是它支持<ruby>自动分页<rt>automatic paging</rt></ruby>。 它的意思是当文件的输出对于屏幕来说太大的时候，<code>bat</code> 命令自动将自己的输出内容传输到 <code>less</code> 命令中，所以你可以一页一页的查看输出内容。</p><p>让我给你看一个例子，使用 <code>cat</code> 命令查看跨多个页面的文件的内容时，提示符会快速跳至文件的最后一页，你看不到内容的开头和中间部分。</p><p>看一下下面的输出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/cat-command-output.png" alt=""></p><p>正如你所看到的，<code>cat</code> 命令显示了文章的最后一页。</p><p>所以你也许需要去将使用 <code>cat</code> 命令的输出传输到 <code>less</code> 命令中去从开头一页一页的查看内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat reverse.py | less</span></span></code></pre></div><p>现在你可以使用回车键去一页一页的查看输出。然而当你使用 <code>bat</code> 命令时这些都是不必要的。<code>bat</code> 命令将自动传输跨越多个页面的文件的输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat reverse.py</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-1.png" alt=""></p><p>现在按下回车键去往下一页。</p><p><code>bat</code> 命令也支持 <ruby>Git 集成<rt><strong>GIT integration</strong></rt></ruby>，这样您就可以轻松查看/编辑 Git 存储库中的文件。 它与 Git 连接可以显示关于索引的修改。（看左栏）</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/bat-command-output-2.png" alt=""></p><h3 id="定制-bat" tabindex="-1">定制 Bat <a class="header-anchor" href="#定制-bat" aria-label="Permalink to “定制 Bat”">​</a></h3><p>如果你不喜欢默认主题，你也可以修改它。Bat 同样有修改它的选项。</p><p>若要显示可用主题，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat --list-themes</span></span>
<span class="line"><span>1337</span></span>
<span class="line"><span>DarkNeon</span></span>
<span class="line"><span>Default</span></span>
<span class="line"><span>GitHub</span></span>
<span class="line"><span>Monokai Extended</span></span>
<span class="line"><span>Monokai Extended Bright</span></span>
<span class="line"><span>Monokai Extended Light</span></span>
<span class="line"><span>Monokai Extended Origin</span></span>
<span class="line"><span>TwoDark</span></span></code></pre></div><p>要使用其他主题，例如 TwoDark，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bat --theme=TwoDark file.txt</span></span></code></pre></div><p>如果你想永久改变主题，在你的 shells 启动文件中加入 <code>export BAT_THEME=&quot;TwoDark&quot;</code>。</p><p><code>bat</code> 还可以选择修改输出的外观。使用 <code>--style</code> 选项来修改输出外观。仅显示 Git 的更改和行号但不显示网格和文件头，请使用 <code>--style=numbers,changes</code>。</p><p>更多详细信息，请参阅 Bat 项目的 GitHub 库（链接在文末）。</p><p>最好，这就是目前的全部内容了。希望这篇文章会帮到你。更多精彩文章即将到来，敬请关注！</p><p>干杯！</p><hr>`,43)),n("p",null,[t[9]||(t[9]=s("via: ",-1)),i(a,{href:"https://www.ostechnix.com/bat-a-cat-clone-with-syntax-highlighting-and-git-integration/"},{default:e(()=>[...t[8]||(t[8]=[s("https://www.ostechnix.com/bat-a-cat-clone-with-syntax-highlighting-and-git-integration/",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=s("作者：",-1)),i(a,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...t[10]||(t[10]=[s("SK",-1)])]),_:1}),t[15]||(t[15]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 译者：",-1)),i(a,{href:"https://github.com/z52527"},{default:e(()=>[...t[12]||(t[12]=[s("z52527",-1)])]),_:1}),t[17]||(t[17]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...t[19]||(t[19]=[s("Linux中国",-1)])]),_:1}),t[22]||(t[22]=s(" 荣誉推出",-1))])])}const y=l(h,[["render",g]]);export{C as __pageData,y as default};
